mapper.sql:
where ID_PROJECT = #{idProject,jdbcType=VARCHAR}

  and FLAG_DELETE <> 'Y'


    and (FLAG_PRIVATE = #{flagPrivate,jdbcType=CHAR}

      or ID_USER = #{viewUserId,jdbcType=VARCHAR}
      or exists (select 1 from task_user tu
                 where tu.ID_TASK = task.ID_TASK
                   and tu.ID_EXE_USER = #{viewUserId,jdbcType=VARCHAR})

    )


  and ID_TASK in
  #{tid,jdbcType=VARCHAR}


  and CD_TASK_TYPE = #{cdTaskType,jdbcType=VARCHAR}


  and CD_TAG = #{cdTag,jdbcType=VARCHAR}


  and CD_STATUS = #{cdStatus,jdbcType=VARCHAR}


  and CD_TASK_GROUP = #{cdTaskGroup,jdbcType=VARCHAR}


  and NAME_TASK like concat('%', #{nameTask,jdbcType=VARCHAR}, '%')


  and ID_USER = #{idUser,jdbcType=VARCHAR}


  and ID_EXE_USER = #{exeUser,jdbcType=VARCHAR}

mapper.select:
select
from task
order by DT_CREATE desc limit #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}

mapper.update:
update task
set FLAG_DELETE = 'Y', DT_DELETE = now()
where ID_TASK = #{idTask,jdbcType=VARCHAR}

update task
set FLAG_DELETE = 'N', DT_DELETE = null
where ID_TASK = #{idTask,jdbcType=VARCHAR}
